-- SELECT-only, 2019-2020 UTC; candidate filters in package selection_metadata.json
WITH base AS (SELECT dateTime,`interval`,usUnits,outTemp,outHumidity,rain,rainRate,windSpeed,LAG(dateTime) OVER(ORDER BY dateTime) prev_dt,LAG(`interval`) OVER(ORDER BY dateTime) prev_interval,LAG(usUnits) OVER(ORDER BY dateTime) prev_units,LAG(outTemp) OVER(ORDER BY dateTime) prev_temp,LAG(outHumidity) OVER(ORDER BY dateTime) prev_rh,LAG(rain) OVER(ORDER BY dateTime) prev_rain,LAG(rainRate) OVER(ORDER BY dateTime) prev_rate,LAG(windSpeed) OVER(ORDER BY dateTime) prev_wind FROM archive WHERE dateTime>=1546299900 AND dateTime<1609459200), c AS (SELECT *,dateTime-prev_dt delta_s FROM base WHERE dateTime>=1546300800 AND dateTime<1609459200 AND dateTime-prev_dt BETWEEN 600 AND 3600 AND `interval`=5 AND prev_interval=5 AND usUnits=16 AND prev_units=16 AND MOD(dateTime-prev_dt,300)=0 AND prev_temp>0 AND outTemp>0 AND prev_temp<=35 AND outTemp<=35 AND prev_rh BETWEEN 20 AND 95 AND outHumidity BETWEEN 20 AND 95 AND prev_rain=0 AND rain=0 AND prev_rate=0 AND rainRate=0 AND prev_wind>=5 AND windSpeed>=5 AND ABS(outTemp-prev_temp)<=2 AND NOT EXISTS(SELECT 1 FROM reconstruction_changes h WHERE h.variable='outTemp' AND h.target_time>prev_dt AND h.target_time<dateTime) AND NOT EXISTS(SELECT 1 FROM reconstruction_changes h WHERE h.variable='outTemp' AND (h.target_time=prev_dt OR h.target_time=dateTime))) SELECT prev_dt left_epoch,dateTime right_epoch,delta_s,prev_temp left_temp_c,outTemp right_temp_c,prev_rh left_rh_pct,outHumidity right_rh_pct,prev_rain left_rain_cm,rain right_rain_cm,prev_rate left_rate,rainRate right_rate,prev_wind left_wind_kmh,windSpeed right_wind_kmh FROM c ORDER BY prev_dt;
